# Verify counts
easy_count = sum(1 for item in questions if item["difficulty"] == "Easy")
medium_count = sum(1 for item in questions if item["difficulty"] == "Medium")
hard_count = sum(1 for item in questions if item["difficulty"] == "Hard")

print(f"Total questions: {len(questions)}")
print(f"  Easy: {easy_count}")
print(f"  Medium: {medium_count}")
print(f"  Hard: {hard_count}")

# Pad if needed to reach exactly 600
target = 200
if easy_count < target or medium_count < target or hard_count < target:
    print(f"\nWARNING: Not all difficulty levels have {target} questions.")
    print(f"  Easy needs {max(0, target - easy_count)} more")
    print(f"  Medium needs {max(0, target - medium_count)} more")
    print(f"  Hard needs {max(0, target - hard_count)} more")

